      `}),l.jsxs("main",{className:"page narrow",children:[l.jsx("h1",{className:"sp-title",children:"Support Mission Phoenix"}),l.jsx("div",{className:"sp-sep"}),l.jsx("p",{className:"sp-lead",children:"Mission Phoenix is a one-man operation built on passion, not profit. Every donation, no matter how small, helps keep this mission alive and growing."}),l.jsx("p",{className:"sp-lead",children:"Your support goes directly towards spreading awareness of the real cost of pornography, maintaining this platform, and building resources to help the next generation avoid the darkness of addiction."}),l.jsxs("a",{href:"https://ko-fi.com/missionphoenix",target:"_blank",rel:"noopener noreferrer",className:"sp-donate",children:[l.jsx("div",{className:"sp-lab",children:"Donate via Ko-Fi"}),l.jsx("div",{className:"sp-url",children:"ko-fi.com/missionphoenix"})]}),l.jsx("p",{className:"sp-thanks",children:"Any amount is greatly appreciated and helpful. Thank you for being part of this mission."})]})]})}function dm(){const e=[{title:"What porn addiction does to your self esteem, and how to rebuild it",date:"03/07/2026",url:"https://buttondown.com/missionphoenix/archive/what-porn-addiction-does-to-your-self-esteem-and/"},{title:"Whats going on in my life right now?",date:"26/06/2026",url:"https://buttondown.com/missionphoenix/archive/whats-going-on-in-my-life-right-now/"},{title:"We are only as sick as our secrets",date:"19/06/2026",url:"https://buttondown.com/missionphoenix/archive/we-are-only-as-sick-as-our-secrets/"},{title:"The myth of the “I’m only harming myself”-excuse",date:"12/06/2026",url:"https://buttondown.com/missionphoenix/archive/the-myth-of-the-i-m-only-harming-myself-excuse/"},{title:"What it feels like to be truly sober",date:"05/06/2026",url:"https://buttondown.com/missionphoenix/archive/what-it-feels-like-to-be-truly-sober/"},{title:"How group vulnerability heals you",date:"29/05/2026",url:"https://buttondown.com/missionphoenix/archive/how-group-vulnerability-heals-you/"},{title:"What you do when nobody is watching",date:"22/05/2026",url:"https://buttondown.com/missionphoenix/archive/what-you-do-when-nobody-is-watching/"},{title:"Finding your life purpose",date:"15/05/2026",url:"https://buttondown.com/missionphoenix/archive/finding-your-life-purpose/"},{title:"Gratitude",date:"08/05/2026",url:"https://buttondown.com/missionphoenix/archive/gratitude/"},{title:"The importance of your subconscious",date:"01/05/2026",url:"https://buttondown.com/missionphoenix/archive/the-importance-of-your-subconscious/"},{title:"The lying and cheating porn addict",date:"24/04/2026",url:"https://buttondown.com/missionphoenix/archive/the-lying-and-cheating-porn-addict/"},{title:"Porn is the killer of creative energy",date:"17/04/2026",url:"https://buttondown.com/missionphoenix/archive/porn-is-the-killer-of-creative-energy/"},{title:"Welcome to the first newsletter of Mission Phoenix",date:"10/04/2026",url:"https://buttondown.com/missionphoenix/archive/welcome-to-the-first-newsletter-of-mission-phoenix/"}];return l.jsxs(l.Fragment,{children:[l.jsx("style",{children:`
